class Solution {
public:
    int constrainedSubsetSum(vector<int>& nums, int k) {
        deque<pair<int, int>> dq;
        int res = nums[0];
        vector<int> dp = nums;
        for (int i = 0; i < nums.size(); ++i) {
            while (!dq.empty() && dq.front().second < i - k) {
                dq.pop_front();
            }
            if (!dq.empty() && dq.front().first > 0) {
                dp[i] += dq.front().first;
            }
            res = max(res, dp[i]);
            while (!dq.empty() && dq.back().first <= dp[i]) {
                dq.pop_back();
            }
            dq.push_back({dp[i], i});
        }
        return res;
    }
};

class Solution {
    public int constrainedSubsetSum(int[] nums, int k) {
        Deque<int[]> dq = new ArrayDeque<>();
        int[] dp = nums.clone();
        int res = nums[0];
        for (int i = 0; i < nums.length; ++i) {
            while (!dq.isEmpty() && dq.peekFirst()[1] < i - k) {
                dq.pollFirst();
            }
            if (!dq.isEmpty() && dq.peekFirst()[0] > 0) {
                dp[i] += dq.peekFirst()[0];
            }
            res = Math.max(res, dp[i]);
            while (!dq.isEmpty() && dq.peekLast()[0] <= dp[i]) {
                dq.pollLast();
            }
            dq.offerLast(new int[]{dp[i], i});
        }
        return res;
    }
}

var constrainedSubsetSum = function(nums, k) {
    const dq = [];
    let head = 0;
    const dp = new Int32Array(nums);
    let res = nums[0];
    for (let i = 0; i < nums.length; ++i) {
        while (head < dq.length && dq[head][1] < i - k) {
            head++;
        }
        if (head < dq.length && dq[head][0] > 0) {
            dp[i] += dq[head][0];
        }
        if (dp[i] > res) res = dp[i];
        while (dq.length > head && dq[dq.length - 1][0] <= dp[i]) {
            dq.pop();
        }
        dq.push([dp[i], i]);
    }
    return res;
};
